void handle_encryption_settings(struct pdf_struct *pdf) {
    if (!pdf->encryption_obj_id_valid || !pdf->file_id) {
        return;
    }

    pdf_obj *enc_obj = pdf_get_obj(pdf->encryption_obj_id);
    size_t enc_obj_size = pdf_obj_size(enc_obj);
    int encrypt_metadata = pdf_dict_get_int(pdf, "/EncryptMetadata", 1);
    int p = pdf_dict_get_int(pdf, "/P", 0);
    int r = pdf_dict_get_int(pdf, "/R", 4);
    int length = pdf_dict_get_int(pdf, "/Length", 40);

    if (r < 2 || r > 5 || length != 40 && length != 128 && length != 256) {
        return;
    }

    pdf_obj *o = pdf_dict_get_obj(pdf, "/O");
    pdf_obj *u = pdf_dict_get_obj(pdf, "/U");

    if (!o || !u) {
        return;
    }

    size_t o_len = pdf_obj_size(o);
    size_t u_len = pdf_obj_size(u);

    if (o_len != 16 && o_len != 32 && o_len != 48 && o_len != 64 &&
        u_len != 16 && u_len != 32 && u_len != 48 && u_len != 64) {
        return;
    }

    char *o_str = (char *)malloc(o_len + 1);
    char *u_str = (char *)malloc(u_len + 1);

    if (!o_str || !u_str) {
        free(o_str);
        free(u_str);
        return;
    }

    memcpy(o_str, pdf_obj_data(o), o_len);
    o_str[o_len] = '\0';
    memcpy(u_str, pdf_obj_data(u), u_len);
    u_str[u_len] = '\0';

    // Log the encryption parameters
    fprintf(stderr, "Encryption settings: R=%d, P=%d, Length=%d, EncryptMetadata=%d\n", r, p, length, encrypt_metadata);

    // Verify user password
    verify_user_password(pdf, o_str, u_str, length);

    free(o_str);
    free(u_str);
}

