    if (!enc_obj || enc_obj->type != obj_dict) {
        return;
    }

    obj *encrypt_metadata = pdf_get_dict_value(enc_obj, "/EncryptMetadata");
    obj *p = pdf_get_dict_value(enc_obj, "/P");
    obj *r = pdf_get_dict_value(enc_obj, "/R");
    obj *length = pdf_get_dict_value(enc_obj, "/Length");

    if (!r || r->type != obj_int) {
        return;
    }

    int r_value = r->i;
    if (r_value < 2 || r_value > 5) {
        return;
    }

    int length_value = 128;
    if (length && length->type == obj_int) {
        length_value = length->i;
        if (length_value != 40 && length_value != 128) {
            return;
        }
    }

    if (p && p->type != obj_int) {
        return;
    }

    obj *o = pdf_get_dict_value(enc_obj, "/O");
    obj *u = pdf_get_dict_value(enc_obj, "/U");

    if (!o || !u || o->type != obj_string || u->type != obj_string) {
        return;
    }

    if (o->string_len != 16 && o->string_len != 32) {
        return;
    }

    if (u->string_len != 16 && u->string_len != 32) {
        return;
    }

